<script setup lang="ts">
import type { Taxon, Category } from '~/types'
import { NModal, useMessage } from 'naive-ui'
definePageMeta({ layout: 'admin' }); useSeoMeta({ title: '\u5206\u7c7b\u4e0e\u6807\u7b7e' })
const api=useApi(), message=useMessage(), confirm=useConfirm()
const { data, error, refresh }=await useFetch<{ tags: Taxon[]; categories: Category[] }>('/api/admin/taxonomy')
const active=ref<'categories'|'tags'>('categories'), page=ref(1), size=10
const show=ref(false), busy=ref(false), editing=ref<Taxon|Category|null>(null)
const form=reactive({name:'',slug:'',sortOrder:0})
const rows=computed(() => active.value==='categories' ? (data.value?.categories||[]) : (data.value?.tags||[]))
const pageRows=computed(() => rows.value.slice((page.value-1)*size,page.value*size))
const modalTitle=computed(() => `${editing.value?'\u7f16\u8f91':'\u65b0\u5efa'}${active.value==='categories'?'\u5206\u7c7b':'\u6807\u7b7e'}`)
const emptyText=computed(() => active.value==='categories'?'\u8fd8\u6ca1\u6709\u6587\u7ae0\u5206\u7c7b\u3002':'\u8fd8\u6ca1\u6709\u6807\u7b7e\u3002')
const newLabel=computed(() => active.value==='categories'?'\u5206\u7c7b':'\u6807\u7b7e')
watch(active,()=>page.value=1)
function open(item?:Taxon|Category){editing.value=item||null;Object.assign(form,{name:item?.name||'',slug:item?.slug||'',sortOrder:(item as Category|undefined)?.sortOrder||0});show.value=true}
async function save(){busy.value=true;try{const endpoint=active.value==='categories'?'/api/admin/taxonomy/categories':'/api/admin/taxonomy/tags';await api(`${endpoint}${editing.value?`/${editing.value.id}`:''}`,{method:editing.value?'PUT':'POST',body:active.value==='categories'?form:{name:form.name,slug:form.slug}});show.value=false;message.success('\u5df2\u4fdd\u5b58');await refresh()}catch(e){message.error(errorText(e))}finally{busy.value=false}}
async function remove(item:Taxon|Category){if(!await confirm(active.value==='categories'?'\u5220\u9664\u5206\u7c7b\uff1f':'\u5220\u9664\u6807\u7b7e\uff1f',`\u786e\u8ba4\u5220\u9664\u201c${item.name}\u201d\uff1f`))return;try{await api(`/api/admin/taxonomy/${active.value}/${item.id}`,{method:'DELETE'});await refresh();if(pageRows.value.length===1&&page.value>1)page.value--;message.success('\u5df2\u5220\u9664')}catch(e){message.error(errorText(e))}}
</script>
<template><div><AdminPageHead title="&#20998;&#31867;&#19982;&#26631;&#31614;&#31649;&#29702;" subtitle="&#25991;&#31456;&#29992;&#20998;&#31867;&#25972;&#29702;&#26639;&#30446;&#65292;&#26631;&#31614;&#29992;&#20110;&#25551;&#36848;&#20869;&#23481;&#20027;&#39064;&#12290;"><button class="primary" @click="open()">&#65291; &#26032;&#24314;{{ newLabel }}</button></AdminPageHead><section class="studio-panel"><div class="admin-tabs"><button :class="{active:active==='categories'}" @click="active='categories'">&#25991;&#31456;&#20998;&#31867;</button><button :class="{active:active==='tags'}" @click="active='tags'">&#26631;&#31614;</button></div><p v-if="error" class="form-error" role="alert">&#21152;&#36733;&#22833;&#36125;&#12290;<button @click="refresh()">&#37325;&#35797;</button></p><div v-for="item in pageRows" :key="item.id" class="tag-manage-row"><span class="tag">{{ item.name }}</span><small>{{ item.count||0 }} &#26465;&#20844;&#24320;&#20869;&#23481;</small><button @click="open(item)">&#32534;&#36753;</button><button class="danger" @click="remove(item)">&#21024;&#38500;</button></div><p v-if="!rows.length" class="admin-empty">{{ emptyText }}</p><Pagination :page="page" :total="rows.length" :size="size" @change="page=$event" /></section><NModal v-model:show="show" preset="card" :title="modalTitle" style="width:min(500px,calc(100% - 30px))"><form @submit.prevent="save"><div class="field"><label for="taxon-name">&#21517;&#31216;</label><input id="taxon-name" v-model="form.name" required maxlength="60"></div><div class="field"><label for="taxon-slug">&#22320;&#22336;&#26631;&#35782;</label><input id="taxon-slug" v-model="form.slug" :disabled="!!editing" required maxlength="80" pattern="[a-z0-9]+(-[a-z0-9]+)*"></div><div v-if="active==='categories'" class="field"><label for="category-order">&#25490;&#24207;</label><input id="category-order" v-model.number="form.sortOrder" type="number" min="0" max="10000"></div><button class="primary" :disabled="busy">&#20445;&#23384;</button></form></NModal></div></template>
